export type MacroCallsMode = 'auto' | 'on' | 'off';
const MACRO_CALLS_MODES: readonly MacroCallsMode[] = ['auto', 'on', 'off'];

/** Index into Core's `MacroCallMode` enum; unknown or missing values are `auto`. */
export function macroCallsToEnum(mode: string | undefined): number {
    return Math.max(0, MACRO_CALLS_MODES.indexOf(mode as MacroCallsMode));
}

const COLOR_SCALE_OPTIONS: SettingOption[] = [
    { value: 'None', label: 'None' },
    { value: 'Gray', label: 'Grayscale' },
    { value: 'Rainbow', label: 'Rainbow' },
    { value: 'Terrain', label: 'Terrain' },
    { value: 'VioletToYellow', label: 'Violet → Yellow' },
    { value: 'GreenToYellow', label: 'Green → Yellow' },
    { value: 'Blues', label: 'Blues' },
    { value: 'BlueToYellow', label: 'Blue → Yellow' },
    { value: 'BlueToRed', label: 'Blue → Red' },
    { value: 'PurpleToYellow', label: 'Purple → Yellow' },
];

/**
 * Which renders are allowed to run `#write`/`#append` — a host setting rather than a `#settings`
 * key, since the backend takes a plain `write` boolean per request. "Report" covers the report
 * layout wherever it is rendered, while the input form and unwrapped never write.
 */
export type WriteMode = 'previewAndReport' | 'reportOnly' | 'manual';

export const WRITE_MODE_OPTIONS: { value: WriteMode; label: string; detail: string }[] = [
    {
        value: 'previewAndReport',
        label: 'Preview and Report',
        detail: 'The Preview and Report views both write, so the files are rewritten as you type. The input form does not.',
    },
    {
        value: 'reportOnly',
        label: 'Report Only',
        detail: 'Only a report render writes: the preview pane switched to Report, and a report export. The Preview view leaves the files alone, so typing does not rewrite them.',
    },
    {
        value: 'manual',
        label: 'Manual',
        detail: 'Nothing writes until you press Write to Disk.',
    },
];

export function coerceWriteMode(raw: string | undefined | null): WriteMode {
    return WRITE_MODE_OPTIONS.some(o => o.value === raw) ? raw as WriteMode : 'reportOnly';
}

/**
 * Verbosity of Calcpad's logging, mirroring the levels in FileLogger.cs. It governs both sides:
 * pushed to the server over /api/calcpad/log-level, and applied locally to what the editor writes
 * to its own output channels.
 */
export type CalcpadLogLevel = 'error' | 'warning' | 'information' | 'verbose';

export const LOG_LEVEL_OPTIONS: { value: CalcpadLogLevel; label: string; detail: string }[] = [
    {
        value: 'error',
        label: 'Error',
        detail: 'Only failures. Crash and hang reports are always written regardless of this setting.',
    },
    {
        value: 'warning',
        label: 'Warning',
        detail: 'Failures plus recoverable problems, such as a missing browser for PDF export. The default, and silent during normal editing.',
    },
    {
        value: 'information',
        label: 'Information',
        detail: 'Adds one-off events: startup, the bound URL, server restarts, shutdown, and browser downloads.',
    },
    {
        value: 'verbose',
        label: 'Verbose',
        detail: 'Adds a line per request, on both the server and the editor. Useful when diagnosing a specific worksheet, noisy otherwise, since editing sends requests continuously.',
    },
];

export function coerceLogLevel(raw: string | undefined | null): CalcpadLogLevel {
    return LOG_LEVEL_OPTIONS.some(o => o.value === raw) ? raw as CalcpadLogLevel : 'warning';
}

/**
 * Whether a render may run `#write`/`#append`, decided from the API's own two flags: `forPrint`
 * is the report layout and `enableUi` is the input form. They never both hold — the server clears
 * `enableUi` for a report — so the three cases below are exhaustive.
